import aioboto3
from botocore.config import Config

from app.core.config import settings

_s3_session = aioboto3.Session()


def get_s3_client():
    """Return an async S3 client context manager configured for MinIO."""
    return _s3_session.client(
        "s3",
        endpoint_url=settings.MINIO_ENDPOINT,
        aws_access_key_id=settings.MINIO_ROOT_USER,
        aws_secret_access_key=settings.MINIO_ROOT_PASSWORD,
        region_name=settings.MINIO_REGION,
        config=Config(signature_version="s3v4", s3={"addressing_style": "path"}),
    )


async def check_storage_connection() -> tuple[bool, str | None]:
    """Verify MinIO connectivity and presence of required buckets."""
    try:
        async with get_s3_client() as client:
            for bucket in (settings.MINIO_VIDEOS_BUCKET, settings.MINIO_THUMBNAILS_BUCKET):
                await client.head_bucket(Bucket=bucket)
        return True, None
    except Exception as exc:
        return False, str(exc)

from typing import Literal

from pydantic import BaseModel, Field


class DependencyStatus(BaseModel):
    """Health status of a single infrastructure dependency."""

    status: Literal["ok", "error"] = Field(..., description="Статус доступности сервиса")
    detail: str | None = Field(default=None, description="Детали ошибки при недоступности")


class HealthResponse(BaseModel):
    """Aggregated health check response for the API and its dependencies."""

    status: Literal["ok", "degraded"] = Field(..., description="Общий статус системы")
    services: dict[str, DependencyStatus] = Field(
        ...,
        description="Статусы зависимостей: postgres, redis, minio",
        examples=[
            {
                "postgres": {"status": "ok", "detail": None},
                "redis": {"status": "ok", "detail": None},
                "minio": {"status": "ok", "detail": None},
            }
        ],
    )

import hashlib
from datetime import datetime, timedelta, timezone
from typing import Any

import jwt
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError

from app.core.config import settings

_pwd_hasher = PasswordHasher()


def hash_password(password: str) -> str:
    """Hash a plaintext password using Argon2id."""
    return _pwd_hasher.hash(password)


def verify_password(plain_password: str, hashed_password: str) -> bool:
    """Verify a plaintext password against an Argon2id hash."""
    try:
        return _pwd_hasher.verify(hashed_password, plain_password)
    except (VerifyMismatchError, Exception):
        return False


def hash_refresh_token(token: str) -> str:
    """Compute SHA-256 hash of a refresh token for safe DB storage."""
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def create_access_token(user_id: str, role: str) -> str:
    """Create a short-lived signed JWT access token."""
    now = datetime.now(timezone.utc)
    expire = now + timedelta(minutes=settings.ACCESS_TOKEN_EXPIRE_MINUTES)
    payload: dict[str, Any] = {
        "sub": user_id,
        "role": role,
        "type": "access",
        "iat": int(now.timestamp()),
        "exp": int(expire.timestamp()),
    }
    return jwt.encode(payload, settings.SECRET_KEY, algorithm=settings.JWT_ALGORITHM)


def decode_access_token(token: str) -> dict[str, Any] | None:
    """Decode and validate a signed JWT access token."""
    try:
        payload = jwt.decode(
            token,
            settings.SECRET_KEY,
            algorithms=[settings.JWT_ALGORITHM],
            options={"require": ["sub", "role", "exp", "type"]},
        )
        if payload.get("type") != "access":
            return None
        return payload
    except (jwt.PyJWTError, Exception):
        return None

from fastapi import HTTPException, status


class DomainException(HTTPException):
    def __init__(self, status_code: int, detail: str):
        super().__init__(status_code=status_code, detail=detail)


class NotFoundException(DomainException):
    def __init__(self, detail: str = "Ресурс не найден"):
        super().__init__(status_code=status.HTTP_404_NOT_FOUND, detail=detail)


class ForbiddenException(DomainException):
    def __init__(self, detail: str = "Недостаточно прав доступа"):
        super().__init__(status_code=status.HTTP_403_FORBIDDEN, detail=detail)


class UnauthorizedException(DomainException):
    def __init__(self, detail: str = "Требуется аутентификация"):
        super().__init__(status_code=status.HTTP_401_UNAUTHORIZED, detail=detail)


class ConflictException(DomainException):
    def __init__(self, detail: str = "Конфликт данных"):
        super().__init__(status_code=status.HTTP_409_CONFLICT, detail=detail)


class BadRequestException(DomainException):
    def __init__(self, detail: str = "Некорректный запрос"):
        super().__init__(status_code=status.HTTP_400_BAD_REQUEST, detail=detail)


class RateLimitException(DomainException):
    def __init__(self, detail: str = "Слишком много запросов. Попробуйте позже."):
        super().__init__(status_code=status.HTTP_429_TOO_MANY_REQUESTS, detail=detail)

