24:     headers.set('Content-Type', 'application/json');
25:   }
26: 
27:   const response = await fetch(url, {
28:     ...options,
29:     headers,
30:     credentials: 'include', // sends cookies
31:   });
32: 
33:   if (!response.ok) {
34:     let errorData: any = null;
35:     let errorMsg = `HTTP Error ${response.status}`;
36:     try {
37:       errorData = await response.json();
38:       errorMsg = errorData.detail || errorMsg;
39:     } catch {
40:       // not json
41:     }
42:     throw new ApiError(response.status, errorMsg, errorData);
43:   }
44: 
45:   if (response.status === 204) {
46:     return {} as T;
47:   }
48: 
49:   return response.json();
50: }

