import React, { useEffect, useState } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { apiRequest } from '../api';
import { Video } from '../types';
import { formatDate, formatDuration, formatViews } from '../utils';
import { Lock, Search as SearchIcon } from 'lucide-react';

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [videos, setVideos] = useState<Video[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!query.trim()) {
      setVideos([]);
      return;
    }

    const fetchSearch = async () => {
      setLoading(true);
      try {
        const data = await apiRequest<Video[]>(`/videos/search?q=${encodeURIComponent(query)}`);
        setVideos(data);
      } catch (err) {
        console.error('Search failed:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchSearch();
  }, [query]);

  return (
    <div className="max-w-5xl mx-auto space-y-6">
      <div className="border-b border-gray-200 dark:border-[#272727] pb-3">
        <h1 className="text-xl font-bold flex items-center gap-2">
          <SearchIcon className="w-5 h-5 text-gray-500" />
          <span>Результаты поиска по запросу «{query}»</span>
        </h1>
      </div>

      {loading ? (
        <div className="space-y-4">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="animate-pulse flex flex-col sm:flex-row gap-4">
              <div className="w-full sm:w-80 aspect-video bg-gray-200 dark:bg-[#272727] rounded-xl shrink-0"></div>
              <div className="flex-1 space-y-3 py-1">
                <div className="h-5 bg-gray-200 dark:bg-[#272727] rounded w-3/4"></div>
                <div className="h-3 bg-gray-200 dark:bg-[#272727] rounded w-1/4"></div>
                <div className="h-3 bg-gray-200 dark:bg-[#272727] rounded w-1/2"></div>
              </div>
            </div>
          ))}
        </div>
      ) : videos.length === 0 ? (
        <div className="text-center py-20 text-gray-500">
          <p className="text-lg">По запросу «{query}» ничего не найдено</p>
          <p className="text-sm mt-1">Попробуйте изменить формулировку запроса</p>
        </div>
      ) : (
        <div className="space-y-4">
          {videos.map((video) => (
            <div
              key={video.id}
              className="flex flex-col sm:flex-row gap-4 group cursor-pointer"
            >
              {/* Horizontal Thumbnail */}
              <Link
                to={`/watch/${video.id}`}
                className="relative w-full sm:w-80 aspect-video rounded-xl overflow-hidden bg-gray-200 dark:bg-[#202020] shrink-0"
              >
                <img
                  src={`/api/v1/videos/${video.id}/thumbnail`}
                  alt={video.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition duration-200"
                  onError={(e) => {
                    (e.target as HTMLImageElement).src =
                      'data:image/svg+xml;charset=UTF-8,%3Csvg%20width%3D%22640%22%20height%3D%22360%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20fill%3D%22%23272727%22%2F%3E%3Ctext%20x%3D%2250%25%22%20y%3D%2250%25%22%20fill%3D%22%23717171%22%20font-size%3D%2220%22%20text-anchor%3D%22middle%22%20dy%3D%22.3em%22%3EYoutube%3C%2Ftext%3E%3C%2Fsvg%3E';
                  }}
                />
                {video.duration_seconds !== null && video.duration_seconds !== undefined && (
                  <div className="absolute bottom-2 right-2 bg-black/80 text-white text-[11px] font-medium px-1.5 py-0.5 rounded">
                    {formatDuration(video.duration_seconds)}
                  </div>
                )}
                {video.visibility === 'private' && (
                  <div className="absolute top-2 left-2 bg-black/80 text-amber-400 text-xs px-2 py-0.5 rounded flex items-center gap-1 font-medium">
                    <Lock className="w-3 h-3" />
                    <span>Приватное</span>
                  </div>
                )}
              </Link>

              {/* Video Info */}
              <div className="flex-1 flex flex-col py-1 overflow-hidden">
                <Link
                  to={`/watch/${video.id}`}
                  className="text-base sm:text-lg font-semibold leading-snug line-clamp-2 hover:text-blue-600 dark:hover:text-blue-400"
                >
                  {video.title}
                </Link>

                <div className="text-xs text-gray-500 dark:text-gray-400 flex items-center gap-1 mt-1">
                  <span>{formatViews(video.views_count)}</span>
                  <span>•</span>
                  <span>{formatDate(video.created_at)}</span>
                </div>

                <Link
                  to={`/channel/${video.owner.username}`}
                  className="flex items-center gap-2 mt-3 hover:opacity-80"
                >
                  <div className="w-6 h-6 rounded-full bg-gradient-to-tr from-purple-600 to-blue-600 text-white font-semibold flex items-center justify-center text-xs shrink-0">
                    {video.owner.username.slice(0, 1).toUpperCase()}
                  </div>
                  <span className="text-xs text-gray-600 dark:text-gray-300 font-medium">
                    {video.owner.channel_name}
                  </span>
                </Link>

                {video.description && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-2 line-clamp-2 leading-relaxed">
                    {video.description}
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { apiRequest } from '../api';
import { ChannelProfile, Video } from '../types';
import { useAuth } from '../context/AuthContext';
import { VideoCard } from '../components/VideoCard';
import { Bell, BellOff, PlusCircle, Video as VideoIcon } from 'lucide-react';

export const ChannelPage: React.FC = () => {
  const { username } = useParams<{ username: string }>();
  const { user } = useAuth();

  const [channel, setChannel] = useState<ChannelProfile | null>(null);
  const [videos, setVideos] = useState<Video[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'videos' | 'about'>('videos');
  const [subscribing, setSubscribing] = useState(false);

  useEffect(() => {
    if (!username) return;

    const fetchChannelData = async () => {
      setLoading(true);
      try {
        const [profile, vids] = await Promise.all([
          apiRequest<ChannelProfile>(`/channels/${username}`),
          apiRequest<Video[]>(`/channels/${username}/videos`),
        ]);
        setChannel(profile);
        setVideos(vids);
      } catch (err) {
        console.error('Failed to load channel:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchChannelData();
  }, [username]);

  const handleSubscribe = async () => {
    if (!user || !channel) return;
    setSubscribing(true);
    try {
      const res = await apiRequest(`/channels/${channel.username}/subscribe`, {
        method: 'POST',
      });
      setChannel({
        ...channel,
        is_subscribed: res.is_subscribed,
        subscribers_count: res.subscribers_count,
      });
    } catch (err) {
      console.error(err);
    } finally {
      setSubscribing(false);
    }
  };

  if (loading) {
    return (
      <div className="max-w-6xl mx-auto space-y-6 animate-pulse">
        <div className="h-40 bg-gray-200 dark:bg-[#272727] rounded-2xl"></div>
        <div className="flex gap-6 items-center">
          <div className="w-24 h-24 rounded-full bg-gray-200 dark:bg-[#272727]"></div>
          <div className="space-y-3 flex-1">
            <div className="h-6 bg-gray-200 dark:bg-[#272727] rounded w-1/3"></div>
            <div className="h-4 bg-gray-200 dark:bg-[#272727] rounded w-1/4"></div>
          </div>
        </div>
      </div>
    );
  }

  if (!channel) {
    return (
      <div className="text-center py-20 text-gray-500">
        <p className="text-xl font-semibold">Канал не найден</p>
        <Link to="/" className="text-blue-500 text-sm mt-2 inline-block">
          Вернуться на главную
        </Link>
      </div>
    );
  }

  const isOwner = user?.username === channel.username;

  return (
    <div className="max-w-6xl mx-auto space-y-6">
      {/* Channel Banner */}
      <div className="h-36 sm:h-48 rounded-2xl bg-gradient-to-r from-red-600 via-purple-600 to-blue-600 flex items-end p-6 text-white shadow-inner"></div>

      {/* Channel Header Profile */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 px-2">
        <div className="flex items-center gap-5">
          <div className="w-20 h-20 sm:w-24 sm:h-24 rounded-full bg-gradient-to-tr from-purple-600 to-blue-600 text-white font-bold flex items-center justify-center text-3xl sm:text-4xl shadow-md">
            {channel.username.slice(0, 1).toUpperCase()}
          </div>
          <div>
            <h1 className="text-2xl sm:text-3xl font-bold">{channel.channel_name}</h1>
            <div className="flex items-center gap-2 text-xs sm:text-sm text-gray-500 dark:text-gray-400 mt-1">
              <span>@{channel.username}</span>
              <span>•</span>
              <span>{channel.subscribers_count} подписчиков</span>
              <span>•</span>
              <span>{videos.length} видео</span>
            </div>
            {channel.channel_description && (
              <p className="text-xs sm:text-sm text-gray-600 dark:text-gray-300 mt-2 line-clamp-1 max-w-xl">
                {channel.channel_description}
              </p>
            )}
          </div>
        </div>

        {/* Subscribe or Upload Button */}
        <div className="flex items-center gap-3">
          {isOwner ? (
            <Link
              to="/upload"
              className="flex items-center gap-2 px-5 py-2.5 rounded-full bg-black text-white dark:bg-white dark:text-black font-semibold text-sm hover:opacity-90 transition"
            >
              <PlusCircle className="w-4 h-4" />
              <span>Загрузить видео</span>
            </Link>
          ) : user ? (
            <button
              onClick={handleSubscribe}
              disabled={subscribing}
              className={`flex items-center gap-2 px-6 py-2.5 rounded-full text-sm font-semibold transition ${
                channel.is_subscribed
                  ? 'bg-gray-200 dark:bg-[#272727] text-gray-800 dark:text-gray-200 hover:bg-gray-300 dark:hover:bg-[#383838]'
                  : 'bg-black text-white dark:bg-white dark:text-black hover:opacity-90'
              }`}
            >
              {channel.is_subscribed ? (
                <>
                  <BellOff className="w-4 h-4" />
                  <span>Вы подписаны</span>
                </>
              ) : (
                <>
                  <Bell className="w-4 h-4" />
                  <span>Подписаться</span>
                </>
              )}
            </button>
          ) : (
            <Link
              to="/login"
              className="px-6 py-2.5 rounded-full bg-black text-white dark:bg-white dark:text-black text-sm font-semibold hover:opacity-90"
            >
              Подписаться
            </Link>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-200 dark:border-[#272727] flex gap-8 px-2 text-sm font-medium">
        <button
          onClick={() => setActiveTab('videos')}
          className={`pb-3 border-b-2 transition ${
            activeTab === 'videos'
              ? 'border-black dark:border-white font-semibold'
              : 'border-transparent text-gray-500 hover:text-black dark:hover:text-white'
          }`}
        >
          Видео ({videos.length})
        </button>
        <button
          onClick={() => setActiveTab('about')}
          className={`pb-3 border-b-2 transition ${
            activeTab === 'about'
              ? 'border-black dark:border-white font-semibold'
              : 'border-transparent text-gray-500 hover:text-black dark:hover:text-white'
          }`}
        >
          О канале
        </button>
      </div>

      {/* Tab Contents */}
      {activeTab === 'videos' ? (
        videos.length === 0 ? (
          <div className="text-center py-20 text-gray-500 space-y-2">
            <VideoIcon className="w-12 h-12 mx-auto stroke-1" />
            <p className="text-lg">На этом канале пока нет опубликованных видео</p>
            {isOwner && (
              <Link
                to="/upload"
                className="inline-block mt-2 text-sm text-blue-600 dark:text-blue-400 hover:underline"
              >
                Опубликовать первое видео
              </Link>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-x-4 gap-y-8">
            {videos.map((video) => (
              <VideoCard key={video.id} video={video} />
            ))}
          </div>
        )
      ) : (
        <div className="max-w-2xl bg-gray-50 dark:bg-[#181818] p-6 rounded-2xl space-y-4">
          <div>
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider">
              Описание
            </h3>
            <p className="mt-2 text-sm leading-relaxed whitespace-pre-wrap">
              {channel.channel_description || 'Автор пока не добавил описание своего канала.'}
            </p>
          </div>
          <div className="pt-4 border-t border-gray-200 dark:border-[#272727] text-xs text-gray-500 space-y-1">
            <p>Дата регистрации: {new Date(channel.created_at).toLocaleDateString()}</p>
            <p>Подписчиков: {channel.subscribers_count}</p>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { UploadCloud, Image as ImageIcon, Lock, Globe, CheckCircle2, AlertCircle } from 'lucide-react';
import { useAuth } from '../context/AuthContext';

export const UploadPage: React.FC = () => {
  const { user } = useAuth();
  const navigate = useNavigate();

  const [videoFile, setVideoFile] = useState<File | null>(null);
  const [thumbFile, setThumbFile] = useState<File | null>(null);
  const [thumbPreview, setThumbPreview] = useState<string | null>(null);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [visibility, setVisibility] = useState<'public' | 'private'>('public');

  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [createdVideoId, setCreatedVideoId] = useState<string | null>(null);

  const videoInputRef = useRef<HTMLInputElement>(null);
  const thumbInputRef = useRef<HTMLInputElement>(null);

  // File drop handler
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      const file = e.dataTransfer.files[0];
      handleVideoSelect(file);
    }
  };

  const handleVideoSelect = (file: File) => {
    // Basic validation
    if (!file.type.startsWith('video/') && !file.name.match(/\.(mp4|webm|mkv|mov)$/i)) {
      setError('Пожалуйста, выберите корректный видеофайл (MP4, WebM, MKV, MOV).');
      return;
    }
    setError(null);
    setVideoFile(file);
    if (!title) {
      // Auto-populate title from filename without extension
      const nameWithoutExt = file.name.replace(/\.[^/.]+$/, '');
      setTitle(nameWithoutExt);
    }
  };

  const handleThumbSelect = (file: File) => {
    if (!file.type.startsWith('image/')) {
      setError('Превью должно быть изображением (JPEG, PNG, WebP).');
      return;
    }
    setThumbFile(file);
    const reader = new FileReader();
    reader.onload = (e) => {
      setThumbPreview(e.target?.result as string);
    };
    reader.readAsDataURL(file);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoFile) {
      setError('Выберите видеофайл для загрузки');
      return;
    }
    if (!title.trim()) {
      setError('Введите название видео');
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);
    setError(null);

    const formData = new FormData();
    formData.append('video', videoFile);
    formData.append('title', title.trim());
    if (description.trim()) {
      formData.append('description', description.trim());
    }
    formData.append('visibility', visibility);
    if (thumbFile) {
      formData.append('thumbnail', thumbFile);
    }

    // Use XMLHttpRequest for real upload progress
    const xhr = new XMLHttpRequest();
    xhr.open('POST', '/api/v1/videos/upload');
    xhr.withCredentials = true;

    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable) {
        const percent = Math.round((event.loaded / event.total) * 100);
        setUploadProgress(percent);
      }
    };

    xhr.onload = () => {
      setIsUploading(false);
      if (xhr.status >= 200 && xhr.status < 300) {
        try {
          const res = JSON.parse(xhr.responseText);
          setCreatedVideoId(res.id);
        } catch {
          navigate('/');
        }
      } else {
        let msg = 'Ошибка при загрузке видео';
        try {
          const res = JSON.parse(xhr.responseText);
          msg = res.detail || msg;
        } catch {}
        setError(msg);
      }
    };

    xhr.onerror = () => {
      setIsUploading(false);
      setError('Сетевая ошибка при загрузке видео. Проверьте соединение.');
    };

    xhr.send(formData);
  };

  if (!user) {
    return (
      <div className="max-w-md mx-auto text-center py-20 space-y-4">
        <UploadCloud className="w-16 h-16 mx-auto text-gray-400 stroke-1" />
        <h2 className="text-xl font-bold">Требуется авторизация</h2>
        <p className="text-sm text-gray-500">
          Чтобы загружать видео на платформу, пожалуйста, войдите в свой аккаунт.
        </p>
        <Link
          to="/login"
          className="inline-block px-6 py-2.5 rounded-full bg-blue-600 text-white font-medium text-sm hover:bg-blue-700"
        >
          Войти
        </Link>
      </div>
    );
  }

  if (createdVideoId) {
    return (
      <div className="max-w-xl mx-auto py-16 text-center space-y-4 bg-white dark:bg-[#181818] p-8 rounded-2xl border border-gray-200 dark:border-[#272727] shadow-sm">
        <CheckCircle2 className="w-16 h-16 mx-auto text-green-500" />
        <h2 className="text-2xl font-bold">Видео успешно загружено!</h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Файл передан на фоновую обработку FFmpeg (транскодирование в H.264/AAC и генерация миниатюры).
          Видео появится в ленте сразу после завершения обработки.
        </p>
        <div className="flex justify-center gap-4 pt-4">
          <Link
            to={`/watch/${createdVideoId}`}
            className="px-6 py-2.5 rounded-full bg-blue-600 text-white text-sm font-semibold hover:bg-blue-700"
          >
            Перейти к видео
          </Link>
          <button
            onClick={() => {
              setCreatedVideoId(null);
              setVideoFile(null);
              setThumbFile(null);
              setThumbPreview(null);
              setTitle('');
              setDescription('');
              setUploadProgress(0);
            }}
            className="px-6 py-2.5 rounded-full bg-gray-100 dark:bg-[#272727] text-sm font-semibold hover:bg-gray-200 dark:hover:bg-[#383838]"
          >
            Загрузить ещё одно
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto py-4 space-y-6">
      <div className="border-b border-gray-200 dark:border-[#272727] pb-4">
        <h1 className="text-2xl font-bold">Загрузка нового видео</h1>
        <p className="text-sm text-gray-500 mt-1">
          Загружайте видео в форматах MP4, WebM, MKV или MOV.
        </p>
      </div>

      {error && (
        <div className="flex items-center gap-3 p-4 rounded-xl bg-red-50 dark:bg-red-950/30 text-red-600 dark:text-red-400 text-sm">
          <AlertCircle className="w-5 h-5 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Drop zone */}
        {!videoFile ? (
          <div
            onDragOver={(e) => e.preventDefault()}
            onDrop={handleDrop}
            onClick={() => videoInputRef.current?.click()}
            className="border-2 border-dashed border-gray-300 dark:border-[#383838] hover:border-blue-500 dark:hover:border-blue-500 rounded-2xl p-12 text-center cursor-pointer transition flex flex-col items-center justify-center space-y-4 bg-gray-50/50 dark:bg-[#121212]"
          >
            <div className="w-16 h-16 rounded-full bg-gray-100 dark:bg-[#202020] flex items-center justify-center text-gray-500">
              <UploadCloud className="w-8 h-8" />
            </div>
            <div>
              <p className="font-semibold text-base">Перетащите видеофайл сюда</p>
              <p className="text-xs text-gray-400 mt-1">или нажмите, чтобы выбрать на компьютере</p>
            </div>
            <span className="text-[11px] text-gray-400">MP4, WebM, MKV, MOV (до 500 МБ)</span>
            <input
              ref={videoInputRef}
              type="file"
              accept="video/mp4,video/webm,video/x-matroska,video/quicktime"
              className="hidden"
              onChange={(e) => {
                if (e.target.files && e.target.files[0]) {
                  handleVideoSelect(e.target.files[0]);
                }
              }}
            />
          </div>
        ) : (
          <div className="flex items-center justify-between p-4 rounded-xl bg-gray-100 dark:bg-[#202020] border border-gray-200 dark:border-[#303030]">
            <div className="flex items-center gap-3 overflow-hidden">
              <UploadCloud className="w-6 h-6 text-blue-500 shrink-0" />
              <div className="overflow-hidden">
                <p className="text-sm font-semibold truncate">{videoFile.name}</p>
                <p className="text-xs text-gray-400">
                  {(videoFile.size / (1024 * 1024)).toFixed(2)} МБ
                </p>
              </div>
            </div>
            <button
              type="button"
              disabled={isUploading}
              onClick={() => setVideoFile(null)}
              className="text-xs text-red-500 hover:underline px-2 py-1"
            >
              Заменить файл
            </button>
          </div>
        )}

        {/* Video metadata */}
        <div className="space-y-4">
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">
              Название (обязательно)
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              disabled={isUploading}
              required
              placeholder="Добавьте название, которое описывает ваше видео"
              className="w-full px-4 py-2.5 rounded-xl bg-transparent border border-gray-300 dark:border-[#383838] focus:border-blue-500 focus:outline-none text-sm"
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">
              Описание
            </label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              disabled={isUploading}
              rows={4}
              placeholder="Расскажите зрителям о своем видео"
              className="w-full px-4 py-2.5 rounded-xl bg-transparent border border-gray-300 dark:border-[#383838] focus:border-blue-500 focus:outline-none text-sm resize-none"
            />
          </div>

          {/* Visibility selection */}
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
              Параметры доступа
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <label
                className={`flex items-start gap-3 p-4 rounded-xl border cursor-pointer transition ${
                  visibility === 'public'
                    ? 'border-blue-500 bg-blue-50/20 dark:bg-blue-950/20'
                    : 'border-gray-200 dark:border-[#303030] hover:bg-gray-50 dark:hover:bg-[#1a1a1a]'
                }`}
              >
                <input
                  type="radio"
                  name="visibility"
                  value="public"
                  checked={visibility === 'public'}
                  onChange={() => setVisibility('public')}
                  className="mt-1"
                />
                <div>
                  <div className="flex items-center gap-1.5 font-semibold text-sm">
                    <Globe className="w-4 h-4 text-green-500" />
                    <span>Открытый доступ (Public)</span>
                  </div>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                    Видео доступно всем пользователям и отображается в ленте и поиске.
                  </p>
                </div>
              </label>

              <label
                className={`flex items-start gap-3 p-4 rounded-xl border cursor-pointer transition ${
                  visibility === 'private'
                    ? 'border-blue-500 bg-blue-50/20 dark:bg-blue-950/20'
                    : 'border-gray-200 dark:border-[#303030] hover:bg-gray-50 dark:hover:bg-[#1a1a1a]'
                }`}
              >
                <input
                  type="radio"
                  name="visibility"
                  value="private"
                  checked={visibility === 'private'}
                  onChange={() => setVisibility('private')}
                  className="mt-1"
                />
                <div>
                  <div className="flex items-center gap-1.5 font-semibold text-sm">
                    <Lock className="w-4 h-4 text-amber-500" />
                    <span>Ограниченный доступ (Private)</span>
                  </div>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
                    Видео можете смотреть только вы и пользователи, которым вы выдадите доступ.
                  </p>
                </div>
              </label>
            </div>
          </div>

          {/* Custom thumbnail */}
          <div>
            <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1.5">
              Значок видео (превью)
            </label>
            <p className="text-xs text-gray-400 mb-2">
              Если превью не выбрано, оно будет сгенерировано автоматически из видео через FFmpeg.
            </p>

            <div className="flex items-center gap-4">
              {thumbPreview ? (
                <div className="relative w-40 aspect-video rounded-lg overflow-hidden border border-gray-300 dark:border-[#383838]">
                  <img src={thumbPreview} alt="Превью" className="w-full h-full object-cover" />
                  <button
                    type="button"
                    onClick={() => {
                      setThumbFile(null);
                      setThumbPreview(null);
                    }}
                    className="absolute top-1 right-1 bg-black/70 text-white rounded-full p-1 text-xs hover:bg-red-600"
                  >
                    ✕
                  </button>
                </div>
              ) : (
                <button
                  type="button"
                  onClick={() => thumbInputRef.current?.click()}
                  className="flex items-center gap-2 px-4 py-2.5 rounded-xl border border-dashed border-gray-300 dark:border-[#383838] text-sm text-gray-600 dark:text-gray-300 hover:border-gray-500"
                >
                  <ImageIcon className="w-4 h-4" />
                  <span>Загрузить значок</span>
                </button>
              )}
              <input
                ref={thumbInputRef}
                type="file"
                accept="image/jpeg,image/png,image/webp"
                className="hidden"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    handleThumbSelect(e.target.files[0]);
                  }
                }}
              />
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        {isUploading && (
          <div className="space-y-2 p-4 rounded-xl bg-blue-50 dark:bg-blue-950/20 border border-blue-200 dark:border-blue-900/50">
            <div className="flex justify-between text-xs font-semibold text-blue-600 dark:text-blue-400">
              <span>Загрузка файла на сервер...</span>
              <span>{uploadProgress}%</span>
            </div>
            <div className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-full overflow-hidden">
              <div
                className="h-full bg-blue-600 transition-all duration-200"
                style={{ width: `${uploadProgress}%` }}
              ></div>
            </div>
          </div>
        )}

        {/* Submit */}
        <div className="flex justify-end gap-3 pt-4 border-t border-gray-200 dark:border-[#272727]">
          <button
            type="button"
            disabled={isUploading}
            onClick={() => navigate('/')}
            className="px-5 py-2.5 rounded-full text-sm font-medium hover:bg-gray-100 dark:hover:bg-[#272727]"
          >
            Отмена
          </button>
          <button
            type="submit"
            disabled={isUploading || !videoFile}
            className="px-6 py-2.5 rounded-full bg-blue-600 text-white text-sm font-semibold hover:bg-blue-700 disabled:opacity-50 transition"
          >
            {isUploading ? 'Загрузка...' : 'Опубликовать'}
          </button>
        </div>
      </form>
    </div>
  );
};

